SELECT MONTH(shipped_date) AS shipped_month, carrier, CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END AS delivered_cohort, COUNT(DISTINCT cost) AS unique_orders, COUNT(*) AS row_count, MIN(shipped_date) AS first_shipped_date FROM shipments WHERE delivered_date > '2023-06-01' AND status IN ('RETURNED', 'LOST') GROUP BY MONTH(shipped_date), carrier, CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END;
